code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    q = (y + dy, x + dx)
                    if 0 <= q[0] < h and 0 <= q[1] < w and grid[q[0]][q[1]] == 5 and q not in seen:
                        seen.add(q)
                        stack.append(q)
            components.append(cells)
    for cells in components:
        top = min(r for r, c in cells)
        bottom = max(r for r, c in cells)
        left = min(c for r, c in cells)
        right = max(c for r, c in cells)
        gaps = [c for c in range(left + 1, right) if grid[top][c] == 0]
        if not gaps:
            continue
        gap = gaps[0]
        for r in range(top + 1, bottom):
            for c in range(left + 1, right):
                if grid[r][c] == 0:
                    out[r][c] = 2
        out[top][gap] = 2
        mid = (left + right) / 2
        if gap < mid:
            for c in range(gap, w):
                out[top - 1][c] = 2
        else:
            for c in range(gap + 1):
                out[top - 1][c] = 2
    return out
'''
